WITH customer_returns AS ( SELECT c.c_customer_sk, c.c_first_name, c.c_last_name, ca.ca_country, cd.cd_gender, SUM(wr.wr_return_amt) AS total_return_amt, SUM(wr.wr_return_quantity) AS total_return_qty FROM web_returns wr JOIN customer c ON wr.wr_refunded_customer_sk = c.c_customer_sk JOIN customer_demographics cd ON wr.wr_refunded_cdemo_sk = cd.cd_demo_sk JOIN customer_address ca ON wr.wr_refunded_addr_sk = ca.ca_address_sk GROUP BY c.c_customer_sk, c.c_first_name, c.c_last_name, ca.ca_country, cd.cd_gender HAVING SUM(wr.wr_return_amt) > 5000 ) SELECT cr.c_customer_sk, cr.c_first_name, cr.c_last_name, cr.ca_country, cr.cd_gender, cr.total_return_amt, cr.total_return_qty, ROW_NUMBER() OVER (PARTITION BY cr.ca_country ORDER BY cr.total_return_qty DESC) AS country_qty_rank FROM customer_returns cr WHERE cr.cd_gender = 'F' ORDER BY cr.total_return_amt DESC
